-file("data/skill_data.erl", 1).

-file("src/mod/data/skill_data.erl", 1).

-module(skill_data).

-lager_records([{combat_buff_data,
		 [bid, name, group, join_type, lev, join_num, duration,
		  buff_result_type, buff_result, desc,
		  positive_or_negative, can_reduce, probability,
		  clean_when_dead, clean_next_wave, is_show, group_pro,
		  dot_type]},
		{effect_data,
		 [bid, group, target_type, target_num, effect_type,
		  hurt_type, base_hit, hit_type, effect_param, condition,
		  condition_param, extra_param, passive_effect,
		  effect_desc]},
		{skill_data,
		 [bid, name, owner, group, next_id, min_play_time, level,
		  is_normal_skill, type, trigger_condition, trigger_param,
		  target, effect_list, add_attr, cd, count, best_target,
		  fit_combat_type, skill_changed, power, is_combat_hidden,
		  priority]},
		{m_skill, [skills_used, skills_owned]}]).

-export([check_skill_data/0, check_skill_data_id/1,
	 check_skill_data_normal/2, check_skill_data_active/2,
	 check_skill_data_passive/2, get_skill/1, get_effect/1,
	 get_buff/1, get_buff_pro/1, get_skill_id_by_group/2]).

